/* SPEC-SUIYIN-ADMIN-092: Nanjing report geometry, Shenzhen saved evidence.
 * Presentation only. Aggregates are derived from the selected saved sessions.
 */
'use strict';
window.AdminQualityReport=(()=>{
 const e=window.Admin.esc;
 const n=x=>x===null||x===undefined?'—':Number(x).toLocaleString('zh-CN');
 const name=s=>s.accountName||s.accountAlias||'工作号未知';
 const customer=s=>s.customerName||s.customerAlias||'客户名称未知';
 const active=r=>(r.sessions||[]).filter(s=>s.analysisStatus!=='excluded');
 const dim=(s,id)=>(s.dimensions||[]).find(d=>Number(d.id)===id);
 const candidate=(s,id)=>dim(s,id)?.conclusion==='candidate';
 const action=(label,act,id='',cls='viewbtn',sessionId='')=>'<button type="button" class="'+cls+'" data-real-action="'+act+'" data-id="'+e(id)+'" data-session-id="'+e(sessionId)+'">'+e(label)+'</button>';
 const link=s=>action('查看对话 ›','session',s.id);
 const pct=(a,b)=>b?(100*a/b).toFixed(1).replace(/\.0$/,'')+'%':'—';
 const kpi=(value,label,small='',color='')=>'<div class="kpi '+color+'"><div class="v">'+n(value)+'</div><div class="l">'+e(label)+'</div><small>'+e(small)+'</small></div>';
 const empty=label=>'<div class="qr-empty">'+e(label||'当前范围没有记录')+'</div>';
 const heading=t=>'<h2>'+e(t)+'</h2>';
 function grid(headers,rows,wide=false){return '<div class="card"><table'+(wide?' class="qr-wide"':'')+'><thead><tr>'+headers.map((h,i)=>'<th scope="col" tabindex="0" data-qr-sort="'+i+'" title="点击排序">'+e(h)+'</th>').join('')+'</tr></thead><tbody>'+(rows.length?rows.map(row=>'<tr>'+row.map((v,i)=>'<td'+(i?' class="num"':'')+'>'+v+'</td>').join('')+'</tr>').join(''):'<tr><td colspan="'+headers.length+'">'+empty()+'</td></tr>')+'</tbody></table></div>';}
 function analyze(r){
  const ss=active(r),issues=(r.issues||[]).filter(i=>i.reviewStatus!=='false_positive'),bySession=new Map(ss.map(s=>[s.id,[]]));
  for(const i of issues)for(const o of i.occurrences||[{sessionId:i.sessionId}])if(bySession.has(o.sessionId))bySession.get(o.sessionId).push(i);
  const high=issues.filter(i=>i.severity==='严重');
  const metric=list=>{
   const ev=list.flatMap(s=>s.responseEvents||[]).filter(v=>v.ownerDate===r.meta.date),waits=ev.filter(v=>v.replyAt).map(v=>v.waitMinutes).filter(v=>v!==null&&Number.isFinite(v)),timingKnown=list.every(s=>Array.isArray(s.responseEvents));
   const ranks=list.map(s=>(bySession.get(s.id)||[]).some(i=>i.risk==='high')?'high':(bySession.get(s.id)||[]).some(i=>i.risk==='medium')?'medium':(bySession.get(s.id)||[]).length?'low':'none');
   return {total:list.length,raw:list.reduce((v,s)=>v+(s.rawBodyMessageCount??0),0),issues:list.reduce((v,s)=>v+(bySession.get(s.id)||[]).length,0),problem:list.filter(s=>(bySession.get(s.id)||[]).length).length,high:ranks.filter(v=>v==='high').length,medium:ranks.filter(v=>v==='medium').length,low:ranks.filter(v=>v==='low').length,clear:ranks.filter(v=>v==='none').length,severe:list.reduce((v,s)=>v+(bySession.get(s.id)||[]).filter(i=>i.severity==='严重').length,0),events:timingKnown?ev.filter(v=>v.timeout===true).length:null,timeout:timingKnown?list.filter(s=>(s.responseEvents||[]).some(v=>v.ownerDate===r.meta.date&&v.timeout===true)).length:null,applicable:timingKnown?list.filter(s=>(s.responseEvents||[]).some(v=>v.ownerDate===r.meta.date)).length:null,unknownTail:ev.filter(v=>v.timeout===null).length,average:waits.length?waits.reduce((a,b)=>a+b,0)/waits.length:null,max:waits.length?Math.max(...waits):null,deep:list.filter(s=>s.metrics?.deepTalk===true).length,interaction:list.filter(s=>candidate(s,5)).length,closing:list.filter(s=>candidate(s,7)).length,unresolved:list.filter(s=>candidate(s,3)).length,solved:list.filter(s=>dim(s,3)?.conclusion==='no_issue').length,referral:list.filter(s=>s.business?.referralMentioned===true).length,products:list.filter(s=>s.business?.largeProductMentioned===true).length,staffProducts:list.filter(s=>['staff','both'].includes(s.business?.largeProductSpeaker)).length,levels:['有效一级','有效二级','有效三级','有效四级','无效'].map(l=>list.filter(s=>s.sourceIntentLevel===l).length),unknown:list.filter(s=>!['有效一级','有效二级','有效三级','有效四级','无效'].includes(s.sourceIntentLevel)).length};
  };
  const map=new Map();for(const s of ss){if(!map.has(s.accountId))map.set(s.accountId,{id:s.accountId,name:name(s),sessions:[]});map.get(s.accountId).sessions.push(s);}
  const groups=[...map.values()].map(g=>({...g,...metric(g.sessions)})).sort((a,b)=>b.problem-a.problem||b.total-a.total);
  return {...metric(ss),ss,issues,highIssues:high,bySession,groups};
 }
 function common(r,x){const top=new Map();for(const i of x.highIssues)top.set(i.dimension,(top.get(i.dimension)||0)+1);return '<div class="kpis">'+kpi(x.total,'质检会话','消息 '+n(x.raw)+' 条','blue')+kpi(x.high,'高风险会话','中 '+n(x.medium)+' / 低 '+n(x.low)+' / 未见候选 '+n(x.clear),'red')+kpi(x.timeout,'超时会话',n(x.events)+' 次（'+(r.snapshot?.rules?.slaMinutes??20)+'分钟线）','orange')+kpi(x.deep,'深聊会话','互动不足候选 '+n(x.interaction),'green')+kpi(x.severe,'红线待复核',[...top].sort((a,b)=>b[1]-a[1]).map(([a,b])=>a+'×'+b).join('，')||'本次未发现严重候选','red')+kpi(x.closing,'收尾待复核','按已保存的归属结论统计','orange')+'</div>';}
 function insight(icon,title,body,cta,tab){return '<div class="insight"><div class="ico">'+icon+'</div><div class="txt"><b>'+e(title)+'</b>'+body+(cta?'<br>'+action(cta,'tab',tab,'act'):'')+'</div></div>';}
 function overview(r,x){
  const timed=[...x.groups].sort((a,b)=>(b.events||0)-(a.events||0)),pending=x.ss.filter(s=>candidate(s,3)),topDims=new Map();for(const i of x.highIssues)topDims.set(i.dimension,(topDims.get(i.dimension)||0)+1);
  const most=[...topDims].sort((a,b)=>b[1]-a[1])[0],top=x.groups.slice(0,3),better=[...x.groups].filter(g=>g.total>=3).sort((a,b)=>a.problem/a.total-b.problem/b.total||b.total-a.total).slice(0,3);
  let html='<div class="insights">';
  html+=insight('🚨','红线待复核 '+n(x.severe)+' 条'+(most?'，最多的是「'+most[0]+'」':''),most?'（'+n(most[1])+'条）。先核对原文及上下文，再确认问题。':'。本次已提供范围内没有严重候选。','查看高风险候选与原文','risk');
  html+=insight('⏱','回复超时 '+n(x.events)+' 次，涉及 '+n(x.timeout)+' 个会话（占适用会话 '+pct(x.timeout,x.applicable)+'）','，'+e(r.snapshot?.rules?.slaMinutes??20)+'分钟标准。<br>超时最多：<b>'+e(timed[0]?.name||'—')+'</b>（'+n(timed[0]?.events)+'次）。最长一次 '+(x.max===null?'—':x.max.toFixed(1))+' 分钟。','查看工作号回复时效','staff');
  html+=insight('👥','问题会话最多：'+(top[0]?.name||'—')+'（'+n(top[0]?.problem)+'个）',top.slice(1).length?'，其次 '+top.slice(1).map(g=>e(g.name)+'（'+n(g.problem)+'个）').join('、')+'。':'','查看工作号排行与明细','staff');
  html+=insight('💎','大单品提出（员工主动）：'+n(x.staffProducts)+' 个会话，占比 '+pct(x.staffProducts,x.total),'（当前为已识别文本记录，业务考核口径待确认）。','查看品项与老带新触达','business');
  html+=insight('💬','未解决诉求候选 '+n(x.unresolved)+' 个，收尾待复核 '+n(x.closing)+' 个','。<br>点击客户名称查看已保存的结论和原文。'+(pending.length?'<div>'+pending.map(s=>action(name(s)+' · '+customer(s),'session',s.id,'chip')).join('')+'</div>':''));
  html+=insight('✅','深聊 '+n(x.deep)+' 个会话，互动不足候选 '+n(x.interaction)+' 个','；诉求解决维度当前未见问题 '+n(x.solved)+' 个。','查看维度质检结果','staff');
  html+=insight('🎯','今日高意向客户：一级 '+n(x.levels[0])+' 个 ｜ 二级 '+n(x.levels[1])+' 个','（合计 '+n(x.levels[0]+x.levels[1])+'，占 '+pct(x.levels[0]+x.levels[1],x.total)+'）——名单与分析依据见「客户意向分级」。','查看高意向客户名单','intent');
  html+='</div><div class="rbgrid"><div class="rbcard"><h3>🔴 需重点关注</h3>'+top.map(g=>'<div class="rbitem"><b>'+e(g.name)+'</b><span>问题'+n(g.problem)+'个·严重'+n(g.severe)+'·超时'+n(g.events)+'次</span></div>').join('')+'</div><div class="rbcard"><h3>🟢 已分析问题较少</h3>'+better.map(g=>'<div class="rbitem good"><b>'+e(g.name)+'</b><span>'+n(g.total)+'会话/'+n(g.problem)+'问题·超时率'+pct(g.timeout,g.applicable)+'</span></div>').join('')+'</div></div>';
  const ordered=[...x.issues].sort((a,b)=>({high:0,medium:1,low:2}[a.risk]??3)-({high:0,medium:1,low:2}[b.risk]??3));
  return html+heading('重点问题 Top10（点击查看对话原文）')+'<div class="card">'+(ordered.slice(0,10).map((i,j)=>{const s=x.ss.find(s=>s.id===i.sessionId);return '<div class="t10item" data-real-action="evidence" data-id="'+e(i.id)+'" tabindex="0" role="button"><span class="t10no">'+(j+1)+'</span><span class="tag">'+e(i.dimension)+'</span><b>'+e(s?name(s):'工作号未知')+'</b><span class="t10cust">'+e(s?customer(s):'')+'</span><span class="t10ev">'+e(i.title)+'</span><span class="viewbtn">查看对话 ›</span></div>';}).join('')||empty())+'</div>';
 }
 function searchbar(placeholder,groups,levels=false){return '<div class="searchbar">'+(levels?'<button class="tabbtn hichip on" data-qr-level="">全部</button><button class="tabbtn hichip" data-qr-level="有效一级">仅一级</button><button class="tabbtn hichip" data-qr-level="有效二级">仅二级</button>':'')+'<select class="qr-list-account" aria-label="按人设工作号筛选"><option value="">全部工作号</option>'+groups.map(g=>'<option value="'+e(g.id)+'">'+e(g.name)+'</option>').join('')+'</select><input type="text" class="qr-list-search" placeholder="'+e(placeholder)+'" aria-label="'+e(placeholder)+'"><span class="count qr-list-count"></span></div>';}
 const searchable=(s,text)=>' data-qr-search-row data-account="'+e(s.accountId)+'" data-level="'+e(s.sourceIntentLevel||'')+'" data-search="'+e(name(s)+' '+customer(s)+' '+text)+'"';
 function intents(r,x){
  const levels=['有效一级（高意向）','有效二级','有效三级','有效四级','当日无回应'],notes=['项目+时间','项目或时间','互动较多','互动较少 / 售后','员工推送未回'];
  const high=x.ss.filter(s=>['有效一级','有效二级'].includes(s.sourceIntentLevel)),ordered=[...x.groups].sort((a,b)=>b.levels[0]-a.levels[0]||b.levels[1]-a.levels[1]);
  let html='<div class="kpis qr-intent-kpis">'+levels.map((l,i)=>kpi(x.levels[i],l,notes[i],['red','orange','blue','',''][i])).join('')+'</div>';
  html+=heading('⭐ 高意向客户名单（一级+二级，按人设工作号分组，点击跳转对话）')+'<div class="card qr-search-area qr-intent-list">'+searchbar('搜索客户 / 意向依据…',ordered,true)+ordered.filter(g=>g.levels[0]+g.levels[1]).map(g=>'<div class="empblock"><div class="emphead"><b>'+e(g.name)+'</b><span class="tag role">工作号</span><span class="count">'+n(g.levels[0]+g.levels[1])+'个高意向（一级'+g.levels[0]+'）</span></div>'+g.sessions.filter(s=>high.includes(s)).map(s=>'<div class="pitem"'+searchable(s,s.intentExplanation||s.summary||'')+'><div class="pline1"><span class="badge '+(s.sourceIntentLevel==='有效一级'?'b-h':'b-m')+'">'+e(s.sourceIntentLevel.replace('有效',''))+'</span> <b>'+e(customer(s))+'</b>'+link(s)+'</div><span class="ptag">意向：'+e(s.sourceIntentLevel)+'</span><div class="pline3">'+e(s.intentExplanation||s.summary||'未提供依据')+'</div></div>').join('')+'</div>').join('')+'<div class="qr-search-empty" hidden>'+empty('没有匹配的高意向客户')+'</div>'+(high.length?'':empty('当前范围没有一级或二级客户'))+'</div>';
  html+=heading('工作号客户意向分布（谁手里高意向多）')+grid(['人设工作号','会话','一级','二级','高意向占比','三级','四级','无回应','未判定'],ordered.map(g=>[e(g.name),n(g.total),'<b class="bad">'+n(g.levels[0])+'</b>',n(g.levels[1]),pct(g.levels[0]+g.levels[1],g.total),n(g.levels[2]),n(g.levels[3]),n(g.levels[4]),n(g.unknown)]));
  html+='<p class="qr-micro-note">未判定 '+n(x.unknown)+' 个；系统消息会话不参与意向分级。当日无回应不代表客户无价值。未提供卡级、项目/时间字段时，以原分析依据为准。</p>';
  return html+heading('全部客户意向明细')+'<div class="card qr-search-area">'+searchbar('搜索客户 / 意向 / 分析依据…',ordered)+'<table><thead><tr><th>客户</th><th>人设工作号</th><th>意向</th><th>AI 分析依据</th><th>操作</th></tr></thead><tbody>'+x.ss.map(s=>'<tr'+searchable(s,s.sourceIntentLevel+' '+(s.intentExplanation||s.summary||''))+'><td>'+e(customer(s))+'</td><td>'+e(name(s))+'</td><td>'+e(s.sourceIntentLevel==='无效'?'当日无回应':s.sourceIntentLevel||'未判定')+'</td><td>'+e(s.intentExplanation||s.summary||'未提供')+'</td><td>'+link(s)+'</td></tr>').join('')+'</tbody></table><div class="qr-search-empty" hidden>'+empty('没有匹配的客户')+'</div></div>';
 }
 function staff(r,x){
  const rows=(r.standards||[]).map(d=>{let yes=0,no=0,na=0,unknown=0,recorded=0;for(const s of x.ss){const v=dim(s,Number(d.id));const insufficient=!v||v.evidenceStatus==='insufficient'||v.conclusion==='unknown';if(insufficient)unknown++;if(v?.applicability==='not_applicable')na++;else if(v?.conclusion==='candidate')no++;else if(v?.conclusion==='recorded')recorded++;else if(v?.conclusion==='no_issue'&&!insufficient)yes++;}return [e(d.id+' '+d.name),n(yes),'<b class="bad">'+n(no)+'</b>',n(na),n(recorded),n(unknown)];});
  const max=Math.max(1,...x.groups.map(g=>g.problem));
  let html=heading('维度质检结果（14维度）')+grid(['维度','未见问题','候选问题','不适用','仅记录','证据不足 / 未判定'],rows);
  html+=heading('问题会话数排行（点击条目在下方展开该工作号问题明细）')+'<div class="card">'+x.groups.filter(g=>g.problem).slice(0,12).map(g=>'<div class="rankrow" role="button" tabindex="0" data-qr-staff="'+e(g.id)+'"><div class="rankname" title="'+e(g.name)+'">'+e(g.name)+'</div><div class="rankbarwrap"><div class="rankbar" style="width:'+100*g.problem/max+'%"></div><span class="ranknum">'+n(g.problem)+'<small>/'+n(g.total)+'会话</small></span><span class="mini">严重'+n(g.severe)+'</span></div></div>').join('')+(x.problem?'':empty('当前范围没有问题候选'))+'<div class="qr-staff-detail" hidden></div></div>';
  html+=heading('工作号全指标对照表')+grid(['人设工作号','会话','消息','超时率%','超时次','平均响应(分)','最长响应(分)','深聊','互动不足','收尾问题','失职收尾','红线','严重','未解决','老带新','未铺垫','高风险','中风险'],x.groups.map(g=>[e(g.name),n(g.total),n(g.raw),pct(g.timeout,g.applicable),n(g.events),g.average===null?'—':g.average.toFixed(1),g.max===null?'—':g.max.toFixed(1),n(g.deep),n(g.interaction),n(g.closing),'—','—',n(g.severe),n(g.unresolved),n(g.referral),n(g.sessions.filter(s=>candidate(s,14)).length),n(g.high),n(g.medium)]),true);
  html+='<p class="qr-micro-note">按人设工作号汇总，实际接待身份未知；严重取已保存的严重候选；红线认定、失职收尾未独立标记时显示 —。证据不足列独立统计，可与候选、不适用、仅记录重叠；不计为符合。</p>';
  html+='<div class="qr-staff-source" hidden>'+x.groups.map(g=>'<div data-staff-source="'+e(g.id)+'"><h3>'+e(g.name)+' · 问题明细</h3>'+issueItems(x.issues.filter(i=>(i.occurrences||[{sessionId:i.sessionId}]).some(o=>g.sessions.some(s=>s.id===o.sessionId))),x,g.id)+'</div>').join('')+'</div>';
  return html;
 }
 function issueItems(items,x,account){return items.flatMap(i=>(i.occurrences||[{sessionId:i.sessionId}]).map(o=>({i,o,s:x.ss.find(s=>s.id===o.sessionId)})).filter(v=>v.s&&(!account||v.s.accountId===account))).map(({i,o,s})=>'<div class="pitem"'+searchable(s,i.title+' '+i.dimension+' '+i.explanation)+'><div class="pline1"><span class="badge '+(i.risk==='high'?'b-h':'b-m')+'">'+e(i.severity||'待复核')+'</span> <b>'+e(customer(s))+'</b> <span class="tag">'+e(i.dimension)+'</span>'+action('查看对话 ›','evidence',i.id,'viewbtn',o.sessionId)+'</div><div class="pline3">'+e(i.baseTitle||i.title)+'</div><div class="pline3">'+e(i.explanation||'')+'</div></div>').join('');}
 function issues(r,x,high){
  const items=high?x.highIssues:x.issues;
  let html='<p class="qr-micro-note">已保存的 AI 候选，待人工复核；同文案合并展示并保留覆盖会话。</p><div class="qr-search-area">'+searchbar('搜索客户 / 维度 / 问题关键词…',x.groups);
  if(high)html+='<div class="card"><table><thead><tr><th>#</th><th>人设工作号</th><th>维度</th><th>证据摘要</th><th>操作</th></tr></thead><tbody>'+items.map((i,j)=>{const s=x.ss.find(s=>s.id===i.sessionId);return '<tr'+(s?searchable(s,i.title+' '+i.explanation+' '+i.dimension):'')+'><td>'+(j+1)+'</td><td>'+e(s?name(s):'')+'</td><td>'+e(i.dimension)+'</td><td>'+e(i.explanation||i.title)+'</td><td>'+action('查看原文 ›','evidence',i.id)+'</td></tr>';}).join('')+'</tbody></table></div>';
  else html+=x.groups.filter(g=>g.problem).map(g=>'<div class="empblock"><div class="emphead"><b>'+e(g.name)+'</b><span class="count">'+n(g.problem)+'个问题会话</span></div>'+issueItems(items.filter(i=>(i.occurrences||[{sessionId:i.sessionId}]).some(o=>g.sessions.some(s=>s.id===o.sessionId))),x,g.id)+'</div>').join('');
  html+='<div class="qr-search-empty" hidden>'+empty('没有匹配的问题')+'</div>'+(items.length?'':empty('当前范围没有此类候选'))+'</div>';
  if(high){const endings=x.ss.filter(s=>candidate(s,7));html+=heading('会话结束归属待复核（'+endings.length+'例）')+'<div class="card"><ul class="clean">'+endings.map(s=>'<li><b>'+e(name(s))+'</b> · '+e(customer(s))+'：'+e(dim(s,7)?.explanation||'')+' '+link(s)+'</li>').join('')+'</ul>'+(endings.length?'':empty())+'</div>';}
  return html;
 }
 function business(r,x){
  const products=new Map(),all=[];for(const s of x.ss)for(const p of s.business?.products||[]){const label=typeof p==='string'?p:p.name;if(!products.has(label))products.set(label,{name:label,total:0,staff:0});const g=products.get(label);g.total++;if(p.speakers?.includes('staff'))g.staff++;all.push({s,p,label});}
  const staffGroups=x.groups.filter(g=>g.staffProducts),ref=x.ss.filter(s=>s.business?.referralMentioned===true),max=Math.max(1,...[...products.values()].map(p=>p.total));
  let html='<div class="kpis qr-business-kpis">'+kpi(x.staffProducts,'员工提出会话','按已识别文本统计','blue')+kpi(x.products,'大单品触达会话','占比 '+pct(x.products,x.total),'green')+kpi(staffGroups.length,'有触达动作的工作号','/'+x.groups.length+'个工作号','blue')+kpi(ref.length,'老带新提及会话','保存记录中的已识别结果','green')+'</div>';
  html+=heading('品项触达排行（按已识别品项的会话数）')+'<div class="card">'+[...products.values()].sort((a,b)=>b.total-a.total).map(p=>'<div class="rankrow"><div class="rankname">'+e(p.name)+'</div><div class="rankbarwrap"><div class="rankbar qr-teal-bar" style="width:'+100*p.total/max+'%"></div><span class="ranknum">'+n(p.total)+'<small>会话 / 员工提及'+p.staff+'</small></span></div></div>').join('')+(all.length?'':empty('本次已保存结果中没有品项记录'))+'</div>';
  html+=heading('工作号触达排行（员工主动提出）')+'<div class="card">'+staffGroups.sort((a,b)=>b.staffProducts-a.staffProducts).map(g=>'<div class="rankrow"><div class="rankname">'+e(g.name)+'</div><div class="rankbarwrap"><div class="rankbar qr-teal-bar" style="width:'+100*g.staffProducts/Math.max(...staffGroups.map(g=>g.staffProducts),1)+'%"></div><span class="ranknum">'+n(g.staffProducts)+'<small>会话 / '+pct(g.staffProducts,g.total)+'</small></span></div></div>').join('')+(staffGroups.length?'':empty())+'</div>';
  html+=heading('大单品触达明细（点击跳转对话）')+'<div class="card qr-search-area">'+searchbar('搜索工作号 / 客户 / 品项…',x.groups)+'<table><thead><tr><th>人设工作号</th><th>客户</th><th>品项</th><th>提及方</th><th>证据序号</th><th>操作</th></tr></thead><tbody>'+all.map(({s,p,label})=>'<tr'+searchable(s,label)+'><td>'+e(name(s))+'</td><td>'+e(customer(s))+'</td><td>'+e(label)+'</td><td>'+e((p.speakers||[]).map(v=>v==='staff'?'员工':v==='customer'?'客户':v).join('、')||'未知')+'</td><td>'+e((p.evidenceSeqs||[]).map(v=>'#'+v).join('、'))+'</td><td>'+link(s)+'</td></tr>').join('')+'</tbody></table><div class="qr-search-empty" hidden>'+empty()+'</div></div>';
  html+=heading('老带新提及明细（'+ref.length+'个会话，点击跳转对话）')+'<div class="card qr-search-area">'+searchbar('搜索工作号 / 客户…',x.groups)+'<table><thead><tr><th>人设工作号</th><th>客户</th><th>保存的分析依据</th><th>操作</th></tr></thead><tbody>'+ref.map(s=>'<tr'+searchable(s,dim(s,14)?.explanation||'')+'><td>'+e(name(s))+'</td><td>'+e(customer(s))+'</td><td>'+e(dim(s,14)?.explanation||'见原文')+'</td><td>'+link(s)+'</td></tr>').join('')+'</tbody></table><div class="qr-search-empty" hidden>'+empty()+'</div></div><p class="qr-micro-note">当前仅显示已有文本识别记录，未解析图片、同义变体可能漏计。采用南京样例品项清单，深圳考核适用性仍待确认。</p>';
  return html;
 }
 function standards(r){const o=r.origin||{},rules=r.snapshot?.rules||{};return '<div class="card"><h3>质检标准（原提示词 '+e(o.sourcePromptVersion||'v1.4')+'）</h3><table><thead><tr><th>维度</th><th>检查内容与保存口径</th></tr></thead><tbody>'+(r.standards||[]).map(d=>'<tr><td>'+e(d.id+' '+d.name)+'</td><td>'+e(d.description)+'</td></tr>').join('')+'</tbody></table><div class="note"><b>参数阈值</b>：回复时效 '+e(rules.slaMinutes)+' 分钟 ｜ 深聊客户发言 ≥'+e(rules.deepTalkSpeechThreshold)+'条 ｜ 连发归组窗口 ≤'+e(rules.customerBurstMinutes)+'分钟<br><b>证据口径</b>：'+e(o.normalizationPolicy||'按保存的逐会话结论和原文证据展示。')+'<br><b>结论状态</b>：候选待人工复核；仅记录、证据不足、不适用分别保留。</div><details class="qr-report-info"><summary>查看完整提示词与本次分析来源</summary><pre class="qr-pre">'+e(r.snapshot?.templateContent||'未提供')+'</pre><p>Prompt SHA256：'+e(o.sourcePromptSha256||'未提供')+'</p>'+(o.ruleDeviations||[]).map(t=>'<p>'+e(t)+'</p>').join('')+'</details></div>';}
 const tabs=[['overview','📋 今日概览'],['intent','🎯 客户意向分级'],['staff','👤 员工看板'],['issues','🔍 问题明细'],['risk','🚨 红线待复核'],['business','💎 大单品&老带新触达'],['standards','📖 质检标准']];
 function content(r,state){const x=analyze(r),counts={intent:x.levels[0]+x.levels[1],issues:x.issues.length,risk:x.severe,standards:r.origin?.sourcePromptVersion||'v1.4'};const nav='<div class="tabs" role="tablist" aria-label="真实日报模块">'+tabs.map(([key,label])=>'<button class="tabbtn'+(state.tab===key?' on':'')+'" role="tab" aria-selected="'+(state.tab===key)+'" data-real-action="tab" data-id="'+key+'">'+e(label)+(counts[key]!==undefined?'<span class="n">'+e(counts[key])+'</span>':'')+'</button>').join('')+'</div>';return nav+common(r,x)+'<div class="tabpane on" role="tabpanel">'+({overview:()=>overview(r,x),intent:()=>intents(r,x),staff:()=>staff(r,x),issues:()=>issues(r,x,false),risk:()=>issues(r,x,true),business:()=>business(r,x),standards:()=>standards(r)}[state.tab]||(()=>overview(r,x)))()+'</div>';}
 function bind(root){
  root.querySelectorAll('.qr-search-area').forEach(area=>{let level='';const apply=()=>{const q=(area.querySelector('.qr-list-search')?.value||'').toLowerCase().trim(),account=area.querySelector('.qr-list-account')?.value||'';let visible=0;area.querySelectorAll('[data-qr-search-row]').forEach(row=>{row.hidden=!!((account&&row.dataset.account!==account)||(level&&row.dataset.level!==level)||(q&&!row.dataset.search.toLowerCase().includes(q)));if(!row.hidden)visible++;});area.querySelectorAll('.empblock').forEach(block=>block.hidden=![...block.querySelectorAll('[data-qr-search-row]')].some(row=>!row.hidden));const counter=area.querySelector('.qr-list-count');if(counter)counter.textContent='共 '+visible+' 条';const none=area.querySelector('.qr-search-empty');if(none)none.hidden=visible>0;};area.querySelector('.qr-list-search')?.addEventListener('input',apply);area.querySelector('.qr-list-account')?.addEventListener('change',apply);area.querySelectorAll('[data-qr-level]').forEach(b=>b.addEventListener('click',()=>{level=b.dataset.qrLevel;area.querySelectorAll('[data-qr-level]').forEach(t=>t.classList.toggle('on',t===b));apply();}));apply();});
  root.querySelectorAll('[data-qr-sort]').forEach(th=>{const sort=()=>{const tbody=th.closest('table').tBodies[0],idx=Number(th.dataset.qrSort),direction=th.getAttribute('aria-sort')==='descending'?1:-1;th.closest('tr').querySelectorAll('th').forEach(t=>t.removeAttribute('aria-sort'));th.setAttribute('aria-sort',direction===1?'ascending':'descending');[...tbody.rows].sort((a,b)=>{const av=a.cells[idx]?.textContent||'',bv=b.cells[idx]?.textContent||'',an=Number(av.replace(/[,%，]/g,'')),bn=Number(bv.replace(/[,%，]/g,''));return direction*(Number.isFinite(an)&&Number.isFinite(bn)?an-bn:av.localeCompare(bv,'zh-CN'));}).forEach(row=>tbody.append(row));};th.addEventListener('click',sort);th.addEventListener('keydown',ev=>{if(ev.key==='Enter')sort();});});
  root.querySelectorAll('[data-qr-staff]').forEach(row=>{const show=()=>{const source=[...root.querySelectorAll('[data-staff-source]')].find(s=>s.dataset.staffSource===row.dataset.qrStaff),target=root.querySelector('.qr-staff-detail');if(source&&target){target.replaceChildren(...[...source.childNodes].map(n=>n.cloneNode(true)));target.hidden=false;}};row.addEventListener('click',show);row.addEventListener('keydown',ev=>{if(ev.key==='Enter')show();});});
 }
 return {content,bind,analyze};
})();
